<script setup lang="ts">import type {Simulation} from '../types/domain';import {percent} from '../utils/format';defineProps<{simulation:Simulation}>();</script><template><div class="table-scroll"><table><thead><tr><th>备选航段</th><th>独占首名</th><th>并列首名</th><th>未获首名</th><th>不可排名</th><th>合计 / 完成样本</th></tr></thead><tbody><tr v-for="r in simulation.alternatives" :key="r.alternative_id"><td><b>{{r.name}}</b><small>{{r.alternative_id}}</small></td><td><b>{{r.exclusive_first}}</b><small>{{percent(r.exclusive_first_share)}}</small></td><td><b>{{r.tied_first}}</b><small>{{percent(r.tied_first_share)}}</small></td><td><b>{{r.not_first}}</b><small>{{percent(r.not_first_share)}}</small></td><td><b>{{r.unrankable}}</b><small>{{percent(r.unrankable_share)}}</small></td><td><b>{{r.counted_samples}} / {{simulation.completed_samples}}</b></td></tr></tbody></table></div><div class="data-caption"><b>声明样本 {{simulation.requested_samples}}</b><span>实际完成 {{simulation.completed_samples}}</span><span>随机种子 {{simulation.seed}}</span><span>{{simulation.status==='partial'?'超时降级为部分结果':'全部样本完成'}}</span></div><p class="caption">{{simulation.distribution}}。{{simulation.degenerate_rule}}；{{simulation.count_rule}}。{{simulation.note}}</p></template>
